1	import { useEffect, useId, useRef } from "react";
2	import { CardImage } from "../../../components/CardImage";
3	import { CheckIcon, ImageIcon, XIcon } from "../../../components/icons";
4	import { ScrollArea } from "../../../components/ScrollArea";
5	import { cardImageUrl } from "../../../lib/api";
6	import {
7	  FOCUS_RING_INSET,
8	  GLASS_DIALOG_GHOST_BUTTON,
9	  GLASS_DIALOG_PANEL,
10	} from "../../../lib/glass";
11	import type { Deck } from "../deckMath";
12	
13	// Which card fronts this deck in the library (P5-6 — the follow-up P5-3 left
14	// room for). The derived default is a heuristic ("the biggest Pokémon") and will
15	// sometimes pick the wall over the attacker beside it; here the owner overrules
16	// it, which is the only answer that is always right.
17	//
18	// AUTOMATIC IS AN EXPLICIT OPTION, not the absence of a choice, so going back to
19	// it is one click rather than a thing you cannot express. It leads the grid, and
20	// deliberately shows no card art: the default is a RULE, and drawing today's
21	// answer to it would read as "this card", which is exactly what it isn't.
22	//
23	// Picking applies immediately — like every other edit in this editor, it rides
24	// the debounced save — so the dialog needs no Save button, only a way out.
25	
26	export interface CoverDialogProps {
27	  open: boolean;
28	  /** The deck's HYDRATED entries — the cards there is art to choose from. */
29	  deck: Deck;
30	  /** The owner's current pick, or null for the derived default. */
31	  chosenCoverCardId: string | null;
32	  /** Pin a card id, or null to go back to automatic. */
33	  onChoose: (cardId: string | null) => void;
34	  onClose: () => void;
35	}
36	
37	const TILE_BASE =
38	  "relative block w-full overflow-hidden rounded-lg ring-1 ring-inset transition-all hover:scale-[1.03] active:scale-95";
39	
40	export function CoverDialog({
41	  open,
42	  deck,
43	  chosenCoverCardId,
44	  onChoose,
45	  onClose,
46	}: CoverDialogProps) {
47	  const dialogRef = useRef<HTMLDialogElement>(null);
48	  const titleId = useId();
49	
50	  // Native <dialog> driven by `open`, exactly like ImportExportDialog: focus
51	  // move-in, focus trapping, Escape and focus restoration for free.
52	  useEffect(() => {
