1	import type { FormEvent } from "react";
2	import { useId, useState } from "react";
3	import { Link } from "react-router-dom";
4	import type { User } from "@luminous/schema";
5	import { CardImage } from "../../components/CardImage";
6	import { SpinnerIcon } from "../../components/icons";
7	import { PlayerAvatar } from "../../components/PlayerAvatar";
8	import { ApiError, cardImageUrl } from "../../lib/api";
9	import { ERROR_TEXT, GLASS_ACCENT_BUTTON, GLASS_INPUT, GLASS_PANEL } from "../../lib/glass";
10	import { useAuth } from "../auth/AuthProvider";
11	import { useDeckLibrary } from "../decks/useDeckLibrary";
12	
13	// The account section of /settings (P5-5 — polish.md "Profiles"). P5-1 made a
14	// lobby seat's name the ACCOUNT's, resolved server-side and broadcast to the
15	// opponent and to spectators — which left a player named by whatever register
16	// picked, with nowhere to change it. This is that surface: the name, and the
17	// generated face (P5-2) drawn from the seed /auth/me now carries.
18	//
19	// It shows the REAL avatar, not a lookalike: the same component the lobby uses,
20	// fed the account's own seed, so "how you appear to other players" is a
21	// statement rather than an approximation. A rename reaches a lobby at the next
22	// hello (apps/api lobby/displayName.ts resolves the seat name there), so a
23	// player already seated elsewhere keeps the old name until they rejoin.
